import math

def main():
    N = int(input())

    M = math.ceil(math.log2(N))
    Q = [[] for _ in range(M)]

    for bit in range(1, N + 1):
        for i in range(M):
            if (bit >> i) & 1:
                Q[i].append(bit)

    print(M)
    for i in range(M):
        print(i + 1, *Q[i])

    S = input().strip()
    ans = 0
    for i in range(M):
        if S[i] == "1":
            ans |= (1 << i)

    print(ans)
